-- Coexistence for one basin (the selected unit, {{ID}}) at one level ({{LEVEL}}).
-- Generated by scripts/build-explorer-sql.sh from coexistence-all.sql, filtered to one basin, so its
-- numbers are identical to the all-basins rows by construction. Scores need every basin, so a
-- live run costs as much as the all-basins query; the app reads precomputed rows.
SELECT * EXCLUDE (id) FROM (
-- Coexistence pillar, every HydroBASINS basin at one level.
-- One row per (id, variable). pct = mid-rank percentile (0-100) among all basins with data,
-- direction applied so higher = more room for coexistence (more protected wetland, more
-- benefits to people, fewer people per km²). pillar_score = mean pct (PROVISIONAL).
-- Unit = a HydroBASINS v1c basin at level {{LEVEL}} (3-6), as H3 res-6 cells (~36 km²).
-- Level-6 basins are polyfilled by cell centre (multipolygons split into parts first, so
-- islands count); each coarser basin is the union of its level-6 basins, matched by
-- Pfafstetter code (a level-n code is the first n digits of its level-6 codes) within the same
-- HydroBASINS region (the first digit of HYBAS_ID: code 353, Chukotka, is split at the
-- antimeridian into regions 3 and 8). Each res-6 cell belongs to one basin. About 1% of
-- level-6 basins, all smaller than one cell, get none.
WITH cells6 AS MATERIALIZED (
  SELECT DISTINCT PFAF_ID AS pfaf6, HYBAS_ID // 1000000000 AS region,
         UNNEST(h3_polygon_wkt_to_cells_experimental(ST_AsText(geom), 6, 'center'))::UBIGINT AS h6
  FROM (SELECT PFAF_ID, HYBAS_ID, UNNEST(ST_Dump(geometry), recursive := true)
        FROM read_parquet('s3://public-hydrobasins/level_06.parquet'))
),
basins AS MATERIALIZED (
  SELECT l.HYBAS_ID AS id, c.h6, h3_cell_to_parent(c.h6, 0)::BIGINT AS h0, h3_cell_area(c.h6, 'km^2') AS a
  FROM cells6 c
  JOIN read_parquet('s3://public-hydrobasins/level_0{{LEVEL}}.parquet') l
    ON l.PFAF_ID = c.pfaf6 // CAST(POW(10, 6 - {{LEVEL}}) AS INTEGER)
   AND l.HYBAS_ID // 1000000000 = c.region
),
units AS (SELECT id, SUM(a) AS area_km2 FROM basins GROUP BY id),
-- Natural wetland area per res-8 cell: GLWD v2 classes 8-32 (lacustrine, riverine, palustrine,
-- ephemeral, peatland and coastal wetlands). Open water (1-7) and rice paddies (33) are left out.
wet8 AS MATERIALIZED (
  SELECT w.h0, w.h8, ANY_VALUE(w.h6) AS h6, SUM(w.area_ha_x10) / 1000.0 AS km2
  FROM read_parquet('s3://public-wetlands/glwd/class-area-hex/Z=*/h0=*/data_0.parquet') w
  WHERE w.Z BETWEEN 8 AND 32
  GROUP BY w.h0, w.h8
),
-- Wetland cells inside any designated protected area (WDPA, excluding 'Proposed') or other
-- effective area-based conservation measure (WD-OECM May 2026); distinct cells, since areas overlap.
pa8 AS (
  SELECT DISTINCT p.h0, p.h8
  FROM read_parquet('s3://public-wdpa/wdpa/hex/h0=*/data_0.parquet') p
  SEMI JOIN wet8 w ON p.h0 = w.h0 AND p.h8 = w.h8
  WHERE p.STATUS <> 'Proposed'
  UNION
  SELECT DISTINCT o.h0, o.h8
  FROM read_parquet('s3://public-wdpa/wdoecm-may-2026/hex/h0=*/data_0.parquet') o
  SEMI JOIN wet8 w ON o.h0 = w.h0 AND o.h8 = w.h8
  WHERE o.STATUS <> 'Proposed'
),
pa AS (
  SELECT b.id, COALESCE(SUM(w.km2) FILTER (WHERE p.h8 IS NOT NULL), 0) / SUM(w.km2) AS v
  FROM wet8 w
  JOIN basins b ON b.h0 = w.h0 AND b.h6 = w.h6
  LEFT JOIN pa8 p ON p.h0 = w.h0 AND p.h8 = w.h8
  WHERE w.km2 > 0
  GROUP BY b.id
),
-- Nature's contributions to people (Chaplin-Kramer et al. 2019): count of the contributions
-- a location ranks highly for (0-19), area-weighted mean over the basin's res-7 cells.
ncp AS (
  SELECT b.id, SUM(n.ncp_only * h3_cell_area(n.h7, 'km^2')) / SUM(h3_cell_area(n.h7, 'km^2')) AS v
  FROM read_parquet('s3://public-ncp/hex/ncp_only/h0=*/data_0.parquet') n
  JOIN basins b ON b.h0 = n.h0 AND b.h6 = n.h6
  WHERE NOT isnan(n.ncp_only)
  GROUP BY b.id
),
-- Population 2020 (GHS-POP R2023A, res-9 sums).
pop AS (
  SELECT b.id, SUM(p.population) AS persons
  FROM read_parquet('s3://public-population/ghs-pop-2020/hex/h0=*/data_0.parquet') p
  JOIN basins b ON b.h0 = p.h0 AND b.h6 = p.h6
  WHERE NOT isnan(p.population)
  GROUP BY b.id
),
vals AS (
  SELECT u.id, 'protected_wetland_share' AS variable, 'Share of wetland protected or conserved' AS label,
         pa.v AS value, 'share' AS unit, 'pct' AS fmt, 'linear' AS scale, 1 AS dir
  FROM units u LEFT JOIN pa USING (id)
  UNION ALL
  SELECT u.id, 'ncp_benefits', 'Nature''s contributions to people',
         ncp.v, 'contributions', 'num1', 'linear', 1
  FROM units u LEFT JOIN ncp USING (id)
  UNION ALL
  SELECT u.id, 'population_density', 'Population density 2020',
         COALESCE(pop.persons, 0) / u.area_km2, 'people/km²', 'num1', 'log', -1
  FROM units u LEFT JOIN pop USING (id)
),
-- Score: mid-rank percentile, 0-100, among units with data. Tied values share
-- the midpoint of their rank range (plain PERCENT_RANK would put every tie at
-- the bottom of the range, e.g. every basin with no protected wetland).
ranked AS (
  SELECT *, CASE WHEN value IS NULL THEN NULL
                 ELSE ROUND(100 * ((RANK() OVER w - 1) + (COUNT(*) OVER w - 1)) / 2.0
                            / NULLIF(COUNT(*) OVER (PARTITION BY variable, value IS NULL) - 1, 0), 1)
            END AS pct
  FROM vals
  WINDOW w AS (PARTITION BY variable, value IS NULL ORDER BY dir * value)
)
-- value is kept to 4 significant figures, which keeps the level-6 files small
SELECT id, variable, label,
       CASE WHEN value IS NULL OR value = 0 THEN value
            ELSE ROUND(value, 3 - CAST(FLOOR(LOG10(ABS(value))) AS INTEGER)) END AS value,
       unit, fmt, scale, dir, pct,
       ROUND(AVG(pct) OVER (PARTITION BY id), 1) AS pillar_score
FROM ranked
ORDER BY id, variable
) WHERE id = {{ID}}
